MATCH (s:T_NHP)
WHERE EXISTS { (s)<-[:DERIVED_FROM*1..12]-(:T_D_FLOW) }
  AND EXISTS { (s)<-[:DERIVED_FROM*1..12]-(:T_D_SEQ) }
RETURN s.id AS id, s.uuid AS uuid, s.type AS type, s.Name AS Name
ORDER BY id
LIMIT 5000

