MATCH (s:Sample)
WHERE EXISTS {
  MATCH (s)-[:IN_PROJECT]->(p:Project)
  WHERE toLower(p.title) CONTAINS toLower($project)
} OR EXISTS {
  MATCH (s)-[:IN_STUDY]->(:Study)-[:IN_INVESTIGATION]->(inv:Investigation)
  WHERE toLower(inv.title) CONTAINS toLower($project)
}
RETURN count(DISTINCT s) AS n

MATCH (st:Study)
WHERE toLower(st.title) CONTAINS toLower($project)
   OR EXISTS {
     MATCH (st)-[:IN_INVESTIGATION]->(inv:Investigation)
     WHERE toLower(inv.title) = toLower($project)
   }
   OR EXISTS {
     MATCH (st)-[:IN_INVESTIGATION]->(:Investigation)-[:IN_PROJECT]->(p:Project)
     WHERE toLower(p.title) = toLower($project)
   }
RETURN DISTINCT st.title AS title, st.id AS id, st.DOI AS DOI, st.PMID AS PMID
ORDER BY title

MATCH (m:T_MUS)
WHERE EXISTS {
  MATCH (seq:T_D_SEQ)-[:DERIVED_FROM*1..12]->(m:T_MUS)
} AND EXISTS {
  MATCH (img:T_D_IMG)-[:DERIVED_FROM*1..12]->(m:T_MUS)
}
RETURN m.id AS id, m.uuid AS uuid, m.type AS type, m.Name AS Name
ORDER BY id
LIMIT 5000

MATCH (s:T_PAT)
WHERE EXISTS {
  MATCH (s)-[:IN_STUDY]->(:Study)-[:IN_INVESTIGATION]->(inv:Investigation)
  WHERE inv.title = $investigation
}
AND EXISTS {
  MATCH (aln:T_A_ALN)-[:DERIVED_FROM*1..12]->(r:T_RNA)-[:DERIVED_FROM*1..12]->(s)
}
RETURN count(s) AS n

MATCH (s:T_PAT)
WHERE toLower(trim(toString(s.Sex))) IN $sex
  AND EXISTS {
    MATCH (s)-[:IN_STUDY]->(st:Study)
    WHERE toLower(st.title) CONTAINS $project
       OR EXISTS {
         MATCH (st)-[:IN_INVESTIGATION]->(inv:Investigation)
         WHERE toLower(inv.title) CONTAINS $project
       }
  }
RETURN count(DISTINCT s) AS n

MATCH (s:Sample)
WHERE toLower(toString(s.Scientist)) CONTAINS toLower($scientist)
  AND (
    EXISTS {
      MATCH (s)-[:IN_PROJECT]->(p:Project)
      WHERE p.title = $project_title
    } OR EXISTS {
      MATCH (s)-[:IN_STUDY]->(:Study)-[:IN_INVESTIGATION]->(inv:Investigation)
      WHERE inv.title = $investigation_title
    }
  )
RETURN count(DISTINCT s) AS n
